export type RelationId = string;

/**
 * The plan-de-pensiones capital-rescate type (LIRPF DT 12ª guidance axis).
 *
 * Attributes: TOTAL: The whole accumulated capital is rescued at once — a
 * single apartado-3 time-window eligibility check applies. PARCIAL: Staged
 * partial withdrawals of the same contingency. Every partial cobro shares the
 * single apartado-3 window measured once from the contingencia year (it does
 * not restart per withdrawal), and a mixed capital/renta rescate may forfeit
 * the transitional régimen.
 */
export type RescateType = "total" | "parcial";

/**
 * Closed vocabulary of why a casilla is a headline figure.
 *
 * `RESULT_INGRESAR` / `RESULT_DEVOLVER` mark the registry-declared result-to-
 * pay / result-to-refund total. `KEY_FIGURE` marks a computed casilla the
 * modelo's verification expectation tracks.
 */
export type ResultSummaryRole =
  "result_ingresar" | "result_devolver" | "key_figure";

/**
 * The product surface that owns a source's data, when one exists.
 */
export type SourceSurface =
  "ledger" | "withholding" | "profile" | "declarations" | "none";

/**
 * Recommended filing mode based on the computed cuota differential.
 *
 * The enum reports the lower-tax path after applying the materiality
 * threshold, or `INDIFFERENT` when the two calculated results differ by less
 * than one euro.
 */
export type TaxationRecommendation = "conjunta" | "individual" | "indifferent";

/**
 * Why the comparison recommends what it does, as a closed token.
 *
 * The words for a reason, with the amounts it rests on, are served by
 * `taxation_comparison_words`.
 */
export type TaxationRecommendationReason =
  "conjunta_lower_result" | "individual_lower_result" | "below_materiality";

/**
 * Closed enumeration of work-unit lifecycle states.
 *
 * * `BORRADOR` — default state at creation. The work unit participates in
 * default listings and accepts mutation (rename, future calculation
 * revisions). * `DESCARTADO` — operator marked the work unit abandoned.
 * Excluded from default listings; mutations are rejected. Revision payloads
 * remain in storage for audit; the work unit cannot be re-activated.
 */
export type WorkUnitState = "borrador" | "descartado";
